    private static async Task<AppUser> EnsureUserAsync(
        AppDbContext dbContext,
        IPasswordHasher<AppUser> passwordHasher,
        string email,
        string fullName,
        UserRole role,
        DateTimeOffset createdAt)
    {
        var normalizedEmail = email.Trim().ToLowerInvariant();
        var existing = await dbContext.Users.FirstOrDefaultAsync(u => u.Email == normalizedEmail);
        if (existing is not null)
            return existing;

        var user = new AppUser
        {
            Id = Guid.CreateVersion7(),
            Email = normalizedEmail,
            FullName = fullName,
            Role = role,
            IsActive = true,
            CreatedAt = createdAt
        };
        user.PasswordHash = passwordHasher.HashPassword(user, "Password123!");

        dbContext.Users.Add(user);
        return user;
    }

    private static Course BuildCourse(
        Guid teacherId,
        Guid categoryId,
        string title,
        string description,
        CourseLevel level,
        CourseStatus status,
        CoverType coverType,
        string coverGradient,
        string coverIcon,
        string? thumbnailUrl,
        DateTimeOffset createdAt,
        (string Title, string Content, string? VideoUrl)[] lessons)
    {
        var courseId = Guid.CreateVersion7();

        return new Course
        {
            Id = courseId,
            TeacherId = teacherId,
            CategoryId = categoryId,
            Title = title,
            Description = description,
            Level = level,
            Status = status,
            CoverType = coverType,
            CoverGradient = coverGradient,
            CoverIcon = coverIcon,
            ThumbnailUrl = thumbnailUrl,
            CreatedAt = createdAt,
            UpdatedAt = createdAt,
            PublishedAt = status == CourseStatus.Published ? createdAt : null,
            Lessons = lessons.Select((l, index) => new Lesson
            {
                Id = Guid.CreateVersion7(),
                CourseId = courseId,
                Title = l.Title,
                Order = index + 1,
                Content = l.Content,
                VideoUrl = l.VideoUrl
            }).ToList()
        };
    }

    private static Exam BuildSampleExam(
        Guid courseId,
        int passMark,
        int? timeLimitMinutes,
        int? maxAttempts)
    {
        var examId = Guid.CreateVersion7();

        var q1Id = Guid.CreateVersion7();
        var q2Id = Guid.CreateVersion7();

        return new Exam
        {
            Id = examId,
            CourseId = courseId,
            PassMarkPercent = passMark,
            TimeLimitMinutes = timeLimitMinutes,
            MaxAttempts = maxAttempts,
            Questions =
            [
                new Question
                {
                    Id = q1Id,
                    ExamId = examId,
                    Text = "Which HTTP status code indicates a newly created resource?",
                    Order = 1,
                    Answers =
                    [
                        new Answer { Id = Guid.CreateVersion7(), QuestionId = q1Id, Text = "200 OK", IsCorrect = false, Order = 1 },
                        new Answer { Id = Guid.CreateVersion7(), QuestionId = q1Id, Text = "201 Created", IsCorrect = true, Order = 2 },
                        new Answer { Id = Guid.CreateVersion7(), QuestionId = q1Id, Text = "204 No Content", IsCorrect = false, Order = 3 }
                    ]
                },
                new Question
                {
                    Id = q2Id,
                    ExamId = examId,
                    Text = "Where should short-lived JWT access tokens be stored on the client to mitigate XSS?",
                    Order = 2,
                    Answers =
                    [
                        new Answer { Id = Guid.CreateVersion7(), QuestionId = q2Id, Text = "In JavaScript memory", IsCorrect = true, Order = 1 },
                        new Answer { Id = Guid.CreateVersion7(), QuestionId = q2Id, Text = "In localStorage", IsCorrect = false, Order = 2 },
                        new Answer { Id = Guid.CreateVersion7(), QuestionId = q2Id, Text = "In URL query parameters", IsCorrect = false, Order = 3 }
                    ]
                }
            ]
        };
    }
